  "svmd.cap1": "{n} lotes, {n} multiplicadores",
  "svmd.cap1.sub": "La restricción de cada lote, yᵢ f(xᵢ) ≥ 1 − ξᵢ, recibe un precio αᵢ ≥ 0. Todos empiezan en 0: todavía no hay calle.",
  "svmd.cap2": "El dual solo ve productos punto",
  "svmd.cap2.sub": "{m} números xᵢᵀxⱼ, la caja 0 ≤ αᵢ ≤ C y una recta Σ αᵢ yᵢ = 0. Nada más sobre los lotes.",
  "svmd.cap3": "Dos multiplicadores a la vez",
  "svmd.cap3.sub": "SMO toma el par que más viola las condiciones de optimalidad y lo resuelve exactamente. El dual solo puede subir.",
  "svmd.cap4": "La brecha se cierra en {n} pasos",
  "svmd.cap4.sub": "El dual sube, el mejor primal baja y se encuentran en {d}: la calle es óptima.",
  "svmd.cap5": "Solo {s} de {n} lotes cuentan",
  "svmd.cap5.sub": "αᵢ = 0 fuera de la calle ({z} lotes), 0 < αᵢ < C en un borde ({f}), αᵢ = C dentro o más allá ({b}).",
  "svmd.cap6": "La calle con solo {s} lotes",
  "svmd.cap6.sub": "w = Σ αᵢ yᵢ xᵢ sobre los vectores de soporte: ancho {w}, primal = dual = {o}.",

  "svmd.lg.spec": "Lote especial (y = +1)",
